import {normalize, escapeHTML as esc, searchEntries, loadList} from './lib.js';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const icons = {
 home:'M3 10 12 3l9 7v10H3Z M9 20v-7h6v7',library:'M4 4h4v16H4Z M11 4h3v16h-3Z M17 4l3-1 3 16-3 1Z',layers:'m3 7 9-4 9 4-9 4Z M3 12l9 4 9-4 M3 17l9 4 9-4',braces:'M8 3H6v7l-3 2 3 2v7h2 M16 3h2v7l3 2-3 2v7h-2',network:'M10 3h4v4h-4Z M3 17h4v4H3Z M10 17h4v4h-4Z M17 17h4v4h-4Z M12 7v5 M5 17v-5h14v5 M12 12v5',cloud:'M6 18a4 4 0 0 1-1-8 7 7 0 0 1 13-1 4.5 4.5 0 0 1 0 9Z',route:'M5 6a2 2 0 1 0 0 .1 M19 18a2 2 0 1 0 0 .1 M7 6h9a4 4 0 0 1 0 8H8a4 4 0 0 0 0 8h9',flask:'M9 3h6 M10 3v7L4 20h16l-6-10V3 M7 15h10',compare:'M4 5h6v14H4Z M14 5h6v14h-6Z',bookmark:'M6 3h12v18l-6-4-6 4Z',sparkles:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',info:'M12 8h.01 M12 11v6 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',search:'M16 16l5 5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',moon:'M20 14A9 9 0 0 1 10 4a9 9 0 1 0 10 10',sun:'M12 3v1 M12 20v1 M3 12h1 M20 12h1 M5.5 5.5l1 1 M17.5 17.5l1 1 M5.5 18.5l1-1 M17.5 6.5l1-1 M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0',motion:'M2 8h5 M2 12h3 M2 16h5 M9 5l10 7-10 7Z',menu:'M4 6h16 M4 12h16 M4 18h16','arrow-up-right':'M6 18 18 6 M6 6h12v12',arrow:'M4 12h16 M14 6l6 6-6 6',back:'M20 12H4 M10 6l-6 6 6 6',check:'m5 12 4 4L19 6',close:'m6 6 12 12 M6 18 18 6',copy:'M8 8h12v13H8Z M16 8V3H3v13h5',code:'m8 6-6 6 6 6 M16 6l6 6-6 6 M14 3l-4 18',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z m-4 9 3 3 5-6',book:'M12 5v16 M12 5C9 3 5 3 2 4v16c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1',clock:'M12 7v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',github:'M9 19c-5 1-5-2-7-2 M15 22v-4c0-1-.3-2-1-2 4-.5 6-2 6-6 0-2-1-3-2-4 0-1 0-3-1-3l-4 2h-3L6 3C5 3 5 5 5 6c-1 1-2 2-2 4 0 4 2 5.5 6 6-1 1-1 2-1 3v3',star:'m12 3 3 6 6 1-4.5 4.5 1 6.5-5.5-3-5.5 3 1-6.5L3 10l6-1Z',palette:'M12 3a9 9 0 1 0 0 18c2 0 2-2 1-3s-1-3 2-3h3c5 0 4-12-6-12 M7 9h.01 M11 6h.01 M16 7h.01 M6 14h.01',play:'m8 4 13 8-13 8Z',reset:'M4 4v6h6 M4 10a8 8 0 1 1 1 8'};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name] || icons.book}"/></svg>`;
function hydrate(root=document){$$('[data-icon]',root).forEach(el=>el.innerHTML=icon(el.dataset.icon));}
const main=$('#main'), labels={architecture:'Arquiteturas',pattern:'Padrões de código',cloud:'Cloud',foundation:'Fundamentos'};
let entries=[], byId=new Map(), favorites=new Set(), completed=new Set(), compared=new Set(), currentPath='', currentQuery=new URLSearchParams(), libraryLimit=24, toastTimer, searchIndex=0, searchResults=[], observer;
const storage={getItem(key){try{return localStorage.getItem(key);}catch{return null}},setItem(key,value){try{localStorage.setItem(key,value);return true;}catch{return false}}};
function persist(name,set){if(!storage.setItem(`atlas-${name}`,JSON.stringify([...set])))toast('O navegador não permitiu salvar. Seu progresso vale nesta sessão.');}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
const routeFor = e => `#/guia/${e.id}`;
const categoryIcon = c => ({pattern:'braces',architecture:'network',cloud:'cloud',foundation:'sparkles'}[c] || 'book');
function entryMark(e){return `<span class="entry-logo">${e.provider ? `<img src="assets/logos/${e.provider}.${e.provider==='gcp'?'png':'svg'}" alt="${esc(e.organization)}">` : icon(categoryIcon(e.category))}</span>`;}
function card(e){return `<article class="entry-card"><div class="card-top">${entryMark(e)}<div class="card-actions"><button class="mini-button ${compared.has(e.id)?'selected':''}" data-action="compare" data-id="${e.id}" aria-label="${compared.has(e.id)?'Remover da comparação':'Comparar'} ${esc(e.name)}" aria-pressed="${compared.has(e.id)}">${icon('compare')}</button><button class="mini-button ${favorites.has(e.id)?'selected':''}" data-action="favorite" data-id="${e.id}" aria-label="${favorites.has(e.id)?'Remover dos favoritos':'Salvar'} ${esc(e.name)}" aria-pressed="${favorites.has(e.id)}">${icon('bookmark')}</button></div></div><span class="card-org">${esc(domain(e))} / ${esc(e.kind)}</span><h3><a class="card-link" href="${routeFor(e)}">${esc(shortName(e))}</a></h3><p class="card-summary">${esc(e.summary)}</p><div class="card-stack">${[...new Set((e.blueprint?.nodes||[]).map(n=>n.technology))].filter(t=>tech[t]?.file).slice(0,4).map(t=>techLogo(t)).join('')}<span>Blueprint · Código · Trade-offs</span></div><div class="card-bottom"><span class="pill">${esc(e.level)}</span><span>${completed.has(e.id)?`<span class="complete-dot">${icon('check')} Estudado</span>`:esc(e.kind)}</span>${icon('arrow-up-right')}</div></article>`;}
function grid(list){return `<div class="entry-grid">${list.map(card).join('')}</div>`;}
function heading(kicker,title,desc){return `<div class="page-top"><span class="eyebrow">${kicker}</span><h1 class="page-title">${title}</h1><p class="page-description">${desc}</p></div>`;}
function empty(title,detail,button=true){return `<div class="empty-state">${icon('search')}<h2>${title}</h2><p>${detail}</p>${button?'<a href="#/biblioteca" class="button primary">Explorar a biblioteca</a>':''}</div>`;}
function count(c){return entries.filter(e=>e.category===c).length;}
function pick(names){return names.map(name=>entries.find(e=>normalize(e.name).includes(normalize(name))) || byId.get(name)).filter(Boolean);}
function home(){
 const architectureCount=entries.filter(e=>e.category==='architecture').length;
 const featured=pick(['MVC','CQRS','Transactional Outbox','Saga','Cache-Aside','Circuit Breaker']).slice(0,6);
 return `<div class="system-hero"><div><span class="eyebrow"><span class="status-dot"></span> THE BACKEND FIELD GUIDE</span><h1>Entenda as peças.<br><em>Projete o sistema.</em></h1><p>Do primeiro endpoint à arquitetura distribuída.<br>Padrões, decisões e implementações explicados por dentro.</p><div class="button-row"><a class="button primary" href="#/biblioteca">Explorar ${entries.length} guias ${icon('arrow')}</a><a class="button subtle" href="#/trilhas">Começar pelos fundamentos ↗</a></div></div><div class="hero-index"><span>SEU REPERTÓRIO DE ENGENHARIA</span><div><strong>${architectureCount}</strong><p>arquiteturas &<br>padrões de sistemas</p></div><div><strong>${count('pattern')}</strong><p>padrões de<br>implementação</p></div><div><strong>${count('cloud')}</strong><p>blueprints em<br>AWS · Azure · GCP</p></div></div></div><div class="workbench-heading"><div><span class="eyebrow">01 / EXPLORE UMA ARQUITETURA</span><h2>Um pedido. Várias responsabilidades.</h2><p>Veja como transação, outbox e processamento assíncrono se conectam.</p></div><a href="#/guia/arch-outbox" class="text-link">Entender o padrão Outbox ↗</a></div>${diagram(orderBlueprint,'Processamento de pedidos · Outbox + worker idempotente')}<div class="stack-ribbon"><span>PEÇAS REAIS.<br>LOGOS OFICIAIS.</span>${['postgresql','redis','kafka','rabbitmq','nginx','docker','kubernetes'].map(t=>`<a href="#/tecnologias" title="${tech[t].name}">${techLogo(t)}<span>${tech[t].name}</span></a>`).join('')}</div><div class="section-heading"><div><span class="eyebrow">02 / EXPLORE POR PROBLEMA</span><h2>O que o seu sistema precisa resolver?</h2></div><a class="text-link" href="#/biblioteca">Ver todo o catálogo ↗</a></div><div class="topic-grid">${[['Arquiteturas','network','Como separar responsabilidades?'],['APIs','code','Como expor e evoluir contratos?'],['Dados','library','Onde o estado vive e se replica?'],['Mensageria','route','Como desacoplar o trabalho?'],['Cache','clock','Como evitar trabalho repetido?'],['Resiliência','shield','O que fazer quando algo falha?'],['Infraestrutura','layers','Como implantar e operar?'],['Cloud','cloud','Quais peças em cada provedor?']].map(([t,i,d])=>`<a class="topic-card" href="#/biblioteca?tema=${encodeURIComponent(t)}"><div>${icon(i)}<span>${entries.filter(e=>domain(e)===t).length} guias</span></div><h3>${t}</h3><p>${d}</p><b>↗</b></a>`).join('')}</div><div class="section-heading"><div><span class="eyebrow">03 / DO CONCEITO À IMPLEMENTAÇÃO</span><h2>Padrões para entender de verdade.</h2><p>Quando usar, como construir e onde cada escolha começa a custar.</p></div><a class="text-link" href="#/trilhas">Ver trilhas de estudo ↗</a></div>${grid(featured)}<section class="cloud-banner"><div><span class="eyebrow">A ARQUITETURA MUDA. OS PRINCÍPIOS CONTINUAM.</span><h2>Três clouds.<br>Decisões que você consegue explicar.</h2><p>Compare serviços por responsabilidade e percorra cada fluxo.</p><a href="#/cloud" class="button primary">Abrir cloud explorer ${icon('arrow')}</a></div><div class="cloud-logos">${['aws','azure','gcp'].map(p=>`<a href="#/cloud?provedor=${p}">${techLogo(p)}<span>${tech[p].name}</span></a>`).join('')}</div></section>`;
}
function library(isFavorites=false){
 const cat=currentQuery.get('categoria')||'',q=currentQuery.get('q')||'',level=currentQuery.get('nivel')||'',kind=currentQuery.get('tipo')||'',sort=currentQuery.get('ordem')||'name',topic=currentQuery.get('tema')||'';
 return `${heading(isFavorites?'SEU REPERTÓRIO':'CATÁLOGO DE SYSTEM DESIGN',isFavorites?'Suas decisões de referência.':'Todo sistema começa com uma pergunta.',isFavorites?'Uma coleção pessoal de padrões de backend. Salve guias para estudar, comparar e aplicar.':'Arquiteturas, padrões de código, dados, comunicação e infraestrutura. Busque o problema, examine o mecanismo e construa a menor solução que faça sentido.')}<div class="catalog-toolbar"><div class="input-wrap">${icon('search')}<label for="catalog-search" class="sr-only">Buscar padrões e arquiteturas</label><input id="catalog-search" type="search" value="${esc(q)}" placeholder="MVC, CQRS, Kafka, consistência, cache, filas…"></div><label class="sr-only" for="level-filter">Nível</label><select id="level-filter"><option value="">Todos os níveis</option>${['Fundamentos','Intermediário','Avançado'].map(v=>`<option ${level===v?'selected':''}>${v}</option>`).join('')}</select><label class="sr-only" for="kind-filter">Tipo</label><select id="kind-filter"><option value="">Todos os tipos</option>${[...new Set(entries.filter(e=>!cat||e.category===cat).map(e=>e.kind))].sort().map(v=>`<option ${kind===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="tabs topic-tabs" aria-label="Áreas de engenharia">${['',...topics].map(t=>`<button class="tab ${topic===t?'active':''}" data-topic="${t}" aria-pressed="${topic===t}">${t||'Tudo'}<span class="tab-count">${t?entries.filter(e=>domain(e)===t).length:entries.length}</span></button>`).join('')}</div><div class="results-bar"><span id="result-count" role="status" aria-live="polite"></span><label>Ordenar <select id="sort-filter"><option value="name" ${sort==='name'?'selected':''}>Nome A–Z</option><option value="level" ${sort==='level'?'selected':''}>Nível de aprendizado</option></select></label></div><div id="library-results"></div>`;
}
function libraryResults(){
 const isFavorites=currentPath==='/favoritos';
 let list=searchEntries(isFavorites?entries.filter(e=>favorites.has(e.id)):entries,$('#catalog-search')?.value||'',{category:currentQuery.get('categoria')||'',level:$('#level-filter')?.value||'',kind:$('#kind-filter')?.value||''});
 const topic=currentQuery.get('tema');if(topic)list=list.filter(e=>domain(e)===topic);
 const levels=['Fundamentos','Intermediário','Avançado'];
 list.sort((a,b)=>($('#sort-filter')?.value==='level'?levels.indexOf(a.level)-levels.indexOf(b.level):0)||a.name.localeCompare(b.name,'pt-BR'));
 $('#result-count').textContent=`${list.length} ${list.length===1?'guia encontrado':'guias encontrados'} · ${Math.min(libraryLimit,list.length)} exibidos`;
 $('#library-results').innerHTML=list.length?`${grid(list.slice(0,libraryLimit))}${list.length>libraryLimit?`<div class="load-more"><button class="button" data-action="more">Mostrar mais ${icon('arrow')}</button><p>${Math.min(libraryLimit,list.length)} de ${list.length} guias</p></div>`:''}`:empty(isFavorites&&!favorites.size?'Sua coleção começa com uma ideia.':'Nenhum resultado por aqui.',isFavorites&&!favorites.size?'Toque no marcador de qualquer guia para salvá-lo.':'Experimente um termo mais curto ou remova os filtros.',isFavorites);
}
function updateLibraryURL(){currentQuery.set('q',$('#catalog-search').value);currentQuery.set('nivel',$('#level-filter').value);currentQuery.set('tipo',$('#kind-filter').value);currentQuery.set('ordem',$('#sort-filter').value==='level'?'level':'');for(const [k,v]of [...currentQuery])if(!v)currentQuery.delete(k);history.replaceState(null,'',`#${currentPath}${currentQuery.size?'?'+currentQuery:''}`);libraryLimit=24;libraryResults();}
const listHTML = items => `<ul>${items.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`;
function article(e){
 if(!e)return empty('Este guia ainda não está no atlas.','Explore o catálogo para encontrar arquiteturas e padrões de backend.');
 const related=(e.related||[]).map(id=>byId.get(id)).filter(Boolean);for(const r of entries.filter(x=>domain(x)===domain(e)&&x.id!==e.id).slice(0,3))if(!related.includes(r))related.push(r);
 const reading=Math.max(4,Math.ceil(JSON.stringify(e).split(/\s+/).length/150));
 const parts=blueprintFor(e),walk=e.walkthrough||[],requirements=e.prerequisites||['Conhecer a linguagem usada no exemplo e seu mecanismo de execução.','Entender o problema descrito antes de introduzir a abstração.'];
 const code=(language,text,key)=>`<div class="code-block"><div class="code-header"><span>${esc(language)} <i>EXEMPLO DE REFERÊNCIA</i></span><button data-action="copy-code" data-id="${e.id}" data-code="${key}">${icon('copy')} Copiar código</button></div><pre><code>${esc(text)}</code></pre></div>`;
 return `<a class="article-back" href="#/biblioteca?tema=${encodeURIComponent(domain(e))}">${icon('back')} ${domain(e)} / Guia de engenharia</a><header class="article-header"><div class="article-meta"><span class="pill blue">${esc(domain(e))}</span><span class="pill">${esc(e.level)}</span><span>${icon('clock')} ${reading} min + prática</span></div><h1>${esc(e.name)}</h1><p>${esc(e.summary)}</p><div class="button-row"><button class="button small ${favorites.has(e.id)?'success':''}" data-action="favorite" data-id="${e.id}" aria-pressed="${favorites.has(e.id)}">${icon('bookmark')} ${favorites.has(e.id)?'Na sua coleção':'Salvar guia'}</button><button class="button small" data-action="compare" data-id="${e.id}" aria-pressed="${compared.has(e.id)}">${icon('compare')} ${compared.has(e.id)?'Remover da comparação':'Comparar decisões'}</button><button class="button small subtle" data-action="copy-link">${icon('copy')} Copiar link</button></div></header><div class="article-section-nav"><a href="#conceito" data-anchor="conceito">01 Conceito</a><a href="#pecas" data-anchor="pecas">02 Peças & fluxo</a><a href="#quando" data-anchor="quando">03 Trade-offs</a><a href="#implementar" data-anchor="implementar">04 Implementação</a><a href="#validar" data-anchor="validar">05 Validação</a></div><section id="pecas" class="blueprint-section">${diagram(parts,`${shortName(e)} · as peças por dentro`)}</section><div class="article-layout"><article class="article-content"><section id="conceito"><span class="section-kicker">01 / MODELO MENTAL</span><h2>Qual problema isso resolve?</h2><p>${esc(e.overview)}</p><div class="concept-note"><span>${icon('info')}</span><p><strong>Padrão não é produto.</strong> O diagrama mostra uma implementação de referência. As responsabilidades importam mais que a marca escolhida para executar cada uma.</p></div></section><section id="quando"><span class="section-kicker">02 / CRITÉRIO DE ESCOLHA</span><h2>Quando usar. E quando parar.</h2>${listHTML(e.when)}<div class="decision-columns"><div class="decision-box"><h3>${icon('check')} Benefícios</h3>${listHTML(e.benefits)}</div><div class="decision-box caution"><h3>${icon('compare')} Trade-offs reais</h3>${listHTML(e.tradeoffs)}</div></div><h3>Quando evitar ou reconsiderar</h3>${listHTML(e.avoid)}</section><section id="implementar"><span class="section-kicker">03 / ENGENHARIA NA PRÁTICA</span><h2>Implemente uma responsabilidade por vez.</h2><details class="requirements" open><summary>Antes de começar</summary>${listHTML(requirements)}</details><div class="steps">${e.steps.map(s=>`<div class="step"><h3>${esc(s.title)}</h3><p>${esc(s.detail)}</p></div>`).join('')}</div>${walk.length?`<div class="implementation-walkthrough"><h2>Descendo até o código</h2>${walk.map((s,i)=>`<div class="walkthrough-step"><span class="walkthrough-number">${String(i+1).padStart(2,'0')}</span><h3>${esc(s.title)}</h3><p>${esc(s.detail)}</p>${s.code?code(s.language||e.example.language,s.code,`walk-${i}`):''}</div>`).join('')}</div>`:''}</section><section id="exemplo"><span class="section-kicker">04 / MECANISMO ESSENCIAL</span><h2>O padrão em uma implementação concreta.</h2>${code(e.example.language,e.example.code,'example')}<div class="code-explanation"><h3>Lendo o exemplo</h3><p>${esc(e.example.explanation)}</p></div>${/^MVC\b/.test(e.name)?`<div class="download-project"><div><strong>Projeto MVC completo para rodar localmente</strong><p>Python + SQLite, separado em model, controller e views, com testes automatizados.</p></div><a class="button primary" href="examples/mvc-python.zip" download>Baixar implementação ↓</a></div>`:''}</section><section id="validar"><span class="section-kicker">05 / PROVE QUE FUNCIONA</span><h2>Teste a promessa e provoque a falha.</h2><div class="decision-box"><h3>O que verificar</h3>${listHTML(e.validation||['Teste o caminho de sucesso e uma entrada inválida; verifique a saída e os efeitos produzidos.','Simule uma dependência indisponível e confirme o comportamento esperado sem esconder a exceção.'])}</div><div class="decision-box caution"><h3>Como isso pode dar errado</h3>${listHTML(e.failureModes||e.tradeoffs)}</div><p class="implementation-note">Exemplo educacional, com escopo declarado no texto. Segurança, compatibilidade de versões, operação e limites do seu ambiente precisam ser validados antes de produção.</p></section><section id="fontes"><span class="section-kicker">06 / FONTES PRIMÁRIAS</span><h2>Vá até a origem da decisão.</h2><div class="source-list">${e.sources.map(s=>`<a class="source-link" href="${esc(s.url)}" target="_blank" rel="noreferrer"><span><strong>${esc(s.label)}</strong><small>${esc(new URL(s.url).hostname)}</small></span>${icon('arrow-up-right')}</a>`).join('')}</div></section><div class="article-finish"><div><h3>Você consegue explicar essa decisão?</h3><p>Registre a leitura e aplique o conceito em um pequeno experimento.</p></div><button class="button ${completed.has(e.id)?'success':'primary'}" data-action="complete" data-id="${e.id}">${icon('check')} ${completed.has(e.id)?'Estudado · desfazer':'Marcar como estudado'}</button></div></article><aside class="article-toc"><span>GUIA DE ENGENHARIA</span><a href="#conceito" data-anchor="conceito">O problema & a ideia</a><a href="#pecas" data-anchor="pecas">Peças e conexões</a><a href="#quando" data-anchor="quando">Benefícios & trade-offs</a><a href="#implementar" data-anchor="implementar">Implementação passo a passo</a><a href="#exemplo" data-anchor="exemplo">Código explicado</a><a href="#validar" data-anchor="validar">Validação & falhas</a><a href="#fontes" data-anchor="fontes">Documentação original</a><div class="reading-progress"><i></i></div><small>DECISÃO → IMPLEMENTAÇÃO → EVIDÊNCIA</small></aside></div><div class="section-heading"><div><h2>Conecte este padrão a outros.</h2></div></div>${grid(related.slice(0,3))}`;
}
function comparison(){const selected=[...compared].map(id=>byId.get(id));return `${heading('ESCOLHAS COM CONTEXTO','Compare antes de decidir.','Compare responsabilidades, garantias e custos. Duas técnicas podem se complementar; antes de escolher, identifique o problema e os limites do seu sistema.')}${selected.length?`<div class="compare-wrap"><table class="comparison-table"><caption class="sr-only">Comparação de referências selecionadas</caption><thead><tr><th scope="col">Critério</th>${selected.map(e=>`<th scope="col">${entryMark(e)}<h2><a href="${routeFor(e)}">${esc(e.name)}</a></h2><button class="button small" data-action="compare" data-id="${e.id}">${icon('close')} Remover</button></th>`).join('')}</tr></thead><tbody>${[['Tipo',e=>esc(e.kind)],['Nível',e=>esc(e.level)],['O problema',e=>esc(e.summary)],['Quando usar',e=>listHTML(e.when)],['Benefícios',e=>listHTML(e.benefits)],['Trade-offs',e=>listHTML(e.tradeoffs)],['Quando evitar',e=>listHTML(e.avoid)],['Próximo passo',e=>`<a class="text-link" href="${routeFor(e)}">Abrir guia completo ${icon('arrow')}</a>`]].map(([title,fn])=>`<tr><th scope="row">${title}</th>${selected.map(e=>`<td>${fn(e)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="control-note">Categorias diferentes resolvem problemas diferentes. CQRS e Event Sourcing, por exemplo, podem se complementar; um não exige o outro.</p><a class="button" href="#/biblioteca">Escolher mais referências ${icon('arrow')}</a>`:empty('Sua próxima decisão começa aqui.','Use o ícone de comparação nos cartões para selecionar até três referências.')}`;}
function tracks(){
 const paths=[
 {icon:'network',title:'Da requisição à regra de negócio',level:'01 · FUNDAMENTOS',desc:'Comece pela entrada HTTP. Entenda MVC, contratos, separação de responsabilidades e transações antes de distribuir o sistema.',names:['MVC','REST','Dependency Injection','Repository','Unit of Work']},
 {icon:'braces',title:'Do código à intenção',level:'02 · INTERMEDIÁRIO',desc:'Separe responsabilidades e reconheça problemas que os padrões resolvem. Depois, experimente o roteador no laboratório.',names:['Strategy','Adapter','Observer','Decorator','Factory Method']},
 {icon:'network',title:'Da aplicação ao sistema',level:'03 · AVANÇADO',desc:'Aprenda a escolher fronteiras, tolerar falhas e lidar com consistência. Escala também é uma questão de simplicidade.',names:['Monólito modular','Hexagonal','CQRS','Transactional Outbox','Saga','Circuit Breaker']},
 {icon:'cloud',title:'Da arquitetura à operação',level:'04 · CLOUD',desc:'Compare os provedores, conheça identidades e eventos e planeje a recuperação antes da primeira falha.',names:[]}
 ];
 paths[3].names=['aws','azure','gcp'].flatMap(provider=>entries.filter(e=>e.provider===provider&&(/landing|serverless|event/i.test(e.name))).slice(0,2)).map(e=>e.id);
 return `${heading('CADA PASSO CONTA','Um caminho para cada momento.','Não é preciso aprender tudo de uma vez. Siga uma sequência, marque os guias estudados e volte aos conceitos quando surgir um problema real.')}<div class="track-grid">${paths.map(t=>{const lessons=pick(t.names),done=lessons.filter(e=>completed.has(e.id)).length,pct=lessons.length?Math.round(done/lessons.length*100):0;return `<section class="track-card"><div class="track-icon">${icon(t.icon)}</div><span class="eyebrow">${t.level}</span><h2>${t.title}</h2><p>${t.desc}</p><div class="track-progress" role="progressbar" aria-label="Progresso em ${t.title}" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><i style="width:${pct}%"></i></div><div class="track-meta"><span>${done} de ${lessons.length} guias estudados</span><strong>${pct}%</strong></div><ol class="track-lessons">${lessons.map((e,i)=>`<li><a href="${routeFor(e)}"><span class="lesson-number ${completed.has(e.id)?'done':''}">${completed.has(e.id)?icon('check'):i+1}</span>${esc(e.name)}${icon('arrow-up-right')}</a></li>`).join('')}</ol></section>`;}).join('')}</div><div class="section-heading"><div><h2>Entender fica melhor quando você experimenta.</h2><p>Depois da leitura, mude uma variável e observe o resultado.</p></div><a class="button" href="#/laboratorio">Ir ao laboratório ${icon('flask')}</a></div>`;
}
function laboratory(){return `${heading('LABORATÓRIO DE BACKEND','Mude uma condição. Observe a consequência.','Experimentos locais para entender cache, invalidação, roteamento e falhas. A simulação mostra decisões e efeitos; não executa serviços de produção.')}${cacheLab()}<div class="section-heading"><div><h2>02 / Por dentro de um alerta</h2><p>Entrada → validação → escolha → uma tentativa de envio.</p></div><span class="pill blue">SOFTWARE & ARQUITETURA</span></div><section class="simulation-layout"><div class="sim-panel"><h2>Você controla o cenário.</h2><p>Se o push estiver habilitado, escolha PUSH. Caso contrário, escolha SMS. Se o canal falhar, a falha é propagada; este exercício não faz fallback nem elimina eventos repetidos.</p><label class="toggle-row" for="sim-push">Push habilitado<input id="sim-push" type="checkbox" checked></label><label class="toggle-row" for="sim-fail">Simular canal indisponível<input id="sim-fail" type="checkbox"></label><label class="toggle-row" for="sim-invalid">Simular evento_id vazio<input id="sim-invalid" type="checkbox"></label><div class="sim-stats"><span><b id="sim-attempts">0</b> tentativas</span><span><b id="sim-success">0</b> sucessos</span></div><div class="button-row"><button class="button primary" data-action="simulate">${icon('play')} Processar evento evt-001</button><button class="button small" data-action="reset-sim" aria-label="Limpar simulação">${icon('reset')}</button></div><p class="control-note">Reprocessar o mesmo ID gera outra tentativa. Idempotência exige um mecanismo adicional, como registro persistente de eventos processados.</p></div><div class="sim-panel"><div class="sim-flow"><div class="sim-node" id="node-input"><div>${icon('code')}</div><span>Entrada</span></div>${icon('arrow')}<div class="sim-node" id="node-validate"><div>${icon('shield')}</div><span>Validação</span></div>${icon('arrow')}<div class="sim-node" id="node-channel"><div>${icon('route')}</div><span>Canal</span></div></div><div class="event-log" id="event-log" role="log" aria-live="polite">Aguardando o primeiro evento…</div></div></section><div class="section-heading"><div><h2>Por que esse fluxo importa?</h2><p>Escolha de canal, injeção de dependência e falhas explícitas são decisões diferentes.</p></div></div><div class="definition-list"><div><h3>Strategy</h3><p>A regra usa um contrato comum para enviar. Um canal concreto pode ser substituído sem alterar o método que processa o alerta.</p></div><div><h3>Adapter</h3><p>Uma integração externa pode ser adaptada ao contrato Canal. O SDK do fornecedor fica isolado do fluxo de negócio.</p></div><div><h3>Validação</h3><p>O evento é recusado antes do efeito externo. Type hints documentam o contrato, mas não validam valores em tempo de execução.</p></div><div><h3>Resiliência</h3><p>Retry, fallback e idempotência precisam de regras explícitas. Adicioná-los sem contexto pode duplicar notificações ou ocultar falhas.</p></div></div>`;}
const cloudProviders={
 aws:{name:'Amazon Web Services',short:'AWS',nodes:[['aws-api','API Gateway','Entrada HTTP','Recebe a requisição, aplica autenticação e limites e encaminha para a função de entrada. Defina quais falhas retornam 4xx ou 5xx.','https://docs.aws.amazon.com/apigateway/latest/developerguide/welcome.html'],['aws-lambda','AWS Lambda','Validar e publicar','Valida o comando e publica em uma fila SQS. Retornar 202 significa que o pedido foi aceito, não que a tarefa terminou.','https://docs.aws.amazon.com/lambda/latest/dg/welcome.html'],['aws-sqs','Amazon SQS','Fila assíncrona','Separa quem recebe de quem processa. Ajuste tempo de visibilidade, retenção e fila de mensagens mortas. Entregas podem se repetir.','https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/welcome.html'],['aws-lambda','AWS Lambda','Consumir e processar','O event source mapping consulta a fila e invoca a função em lotes. Trate falhas parciais e faça efeitos idempotentes para sobreviver a reentregas.','https://docs.aws.amazon.com/lambda/latest/dg/with-sqs.html'],['aws-dynamodb','DynamoDB','Persistir o resultado','Grava estado e resultado. Escritas condicionais podem ajudar a reconhecer uma operação repetida; defina a chave de negócio antes de escolher a partição.','https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/Expressions.ConditionExpressions.html']]},
 azure:{name:'Microsoft Azure',short:'Azure',nodes:[['azure-api','API Management','Entrada HTTP','Publica e protege a API, aplica políticas e encaminha ao backend. A camada de gerenciamento não substitui a autorização dentro do domínio.','https://learn.microsoft.com/en-us/azure/api-management/api-management-key-concepts'],['azure-functions','Azure Functions','Validar e publicar','Uma função HTTP valida o pedido e envia uma mensagem ao Service Bus. Prefira identidades gerenciadas a segredos fixos nas integrações compatíveis.','https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview'],['azure-servicebus','Service Bus','Fila assíncrona','Mantém mensagens até serem processadas. O modo Peek-Lock permite concluir, abandonar ou enviar para dead-letter; o bloqueio pode expirar.','https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview'],['azure-functions','Azure Functions','Consumir e processar','O gatilho do Service Bus executa o processamento. Ajuste concorrência e renovação de lock, e confirme a mensagem somente depois do trabalho relevante.','https://learn.microsoft.com/en-us/azure/azure-functions/functions-bindings-service-bus-trigger'],['azure-cosmos','Azure Cosmos DB','Persistir o resultado','Escolha chave de partição e consistência de acordo com as consultas e requisitos. Transações de lote têm escopo de partição lógica.','https://learn.microsoft.com/en-us/azure/cosmos-db/partitioning-overview']]},
 gcp:{name:'Google Cloud',short:'Google Cloud',nodes:[['gcp-api','API Gateway','Entrada HTTP','Publica uma API definida em OpenAPI e encaminha ao serviço Cloud Run. Proteja a invocação do backend e valide identidade e autorização.','https://cloud.google.com/api-gateway/docs/about-api-gateway'],['gcp-run','Cloud Run','Validar e publicar','Executa um contêiner HTTP que valida a entrada e publica no Pub/Sub. Defina limites de instâncias e concorrência conforme a capacidade das dependências.','https://cloud.google.com/run/docs/overview/what-is-cloud-run'],['gcp-pubsub','Pub/Sub','Tópico + assinatura','Distribui eventos por assinaturas. Aqui, uma assinatura push autenticada entrega ao consumidor. Reentregas exigem processamento idempotente.','https://cloud.google.com/pubsub/docs/push'],['gcp-run','Cloud Run','Consumir e processar','Um endpoint recebe a mensagem push, valida o envelope e processa o trabalho. A resposta HTTP de sucesso confirma a entrega; falhas podem provocar novas tentativas.','https://cloud.google.com/run/docs/tutorials/pubsub'],['gcp-firestore','Firestore','Persistir o resultado','Armazena documentos do resultado. Transações podem coordenar leitura e escrita, com reexecução em conflitos; evite efeitos externos no corpo transacional.','https://cloud.google.com/firestore/native/docs/manage-data/transactions']]}
};
let cloudProvider='aws',cloudNode=0;
function cloudExplorer(){const p=cloudProviders[cloudProvider];return `${heading('EXPLORE O QUE ESTÁ POR TRÁS','A mesma intenção. Outras escolhas.','Um fluxo de processamento assíncrono em três provedores. Clique nos serviços para entender responsabilidades, fronteiras e cuidados de implementação.')}<div class="cloud-provider-tabs" role="group" aria-label="Provedor cloud">${Object.entries(cloudProviders).map(([id,prov])=>`<button class="provider-button ${id===cloudProvider?'active':''}" data-provider="${id}" aria-pressed="${id===cloudProvider}"><img src="assets/logos/${id}.${id==='gcp'?'png':'svg'}" alt="">${prov.short}</button>`).join('')}</div><section class="cloud-canvas"><div class="canvas-header"><h2>Receber agora. Processar de forma assíncrona.</h2><small>${p.name} · arquitetura didática</small></div><div class="architecture-flow">${p.nodes.map(([img,name,role],i)=>`<button class="cloud-node ${i===cloudNode?'active':''}" data-node="${i}" aria-pressed="${i===cloudNode}"><img src="assets/logos/${img}.svg" alt="Ícone oficial ${name}"><b>${name}</b><small>${role}</small></button>`).join('')}</div><div id="cloud-node-detail" class="cloud-node-detail" aria-live="polite">${cloudNodeDetail()}</div><div class="cloud-annotation"><span>${icon('shield')} Identidade, observabilidade e segurança atravessam todo o fluxo.</span><span>${icon('info')} Aceitar o pedido ≠ concluir o processamento.</span></div></section><p class="control-note">Diagrama de responsabilidades, não um template pronto para produção. Os serviços são alternativas por papel, com semânticas, limites e preços diferentes. O Google Cloud disponibiliza ícones novos e de console legado; ambos estão identificados nos créditos.</p><div class="section-heading"><div><h2>Traduza a intenção, não apenas o nome.</h2><p>Equivalência funcional não significa compatibilidade direta.</p></div></div><div class="equivalence-wrap"><table class="equivalence-table"><caption class="sr-only">Serviços por responsabilidade e provedor</caption><thead><tr><th scope="col">Responsabilidade</th><th scope="col">AWS</th><th scope="col">Azure</th><th scope="col">Google Cloud</th></tr></thead><tbody>${[['Expor e gerenciar API','API Gateway','API Management','API Gateway / Apigee'],['Executar função ou contêiner','Lambda / ECS / EKS','Functions / Container Apps / AKS','Cloud Run / GKE'],['Desacoplar mensagens','SQS / SNS / EventBridge','Service Bus / Event Grid','Pub/Sub / Eventarc'],['Dados de documentos e chave-valor','DynamoDB','Cosmos DB','Firestore'],['Observabilidade','CloudWatch / X-Ray','Azure Monitor','Cloud Monitoring / Trace']].map(row=>`<tr><th scope="row">${row[0]}</th>${row.slice(1).map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="section-heading"><div><h2>Aprofunde em ${p.short}</h2><p>Identidade, operação, eventos e recuperação de desastres.</p></div><a class="text-link" href="#/biblioteca?categoria=cloud">Todos os guias cloud ${icon('arrow')}</a></div>${grid(entries.filter(e=>e.provider===cloudProvider))}`;}
function cloudNodeDetail(){const n=cloudProviders[cloudProvider].nodes[cloudNode];return `<h3>${cloudNode+1}. ${n[1]} · ${n[2]}</h3><p>${n[3]}</p><a href="${n[4]}" class="text-link" target="_blank" rel="noreferrer">Documentação oficial ${icon('arrow-up-right')}</a>`;}
function about(){return `${heading('O PROPÓSITO DO ATLAS','Uma biblioteca de engenharia.<br>Feita para pensar sistemas.','System Design é o estudo das decisões que conectam regras de negócio, comunicação, dados e operação. Este portal existe para tornar essas decisões visíveis, discutíveis e implementáveis.')}<article class="about-content article-content"><section><h2>O que está no catálogo</h2><p>São ${entries.length} guias de backend: ${count('architecture')} padrões e estilos arquiteturais, ${count('pattern')} padrões de implementação, ${count('cloud')} arquiteturas cloud e ${count('foundation')} fundamentos. Cada guia reúne contexto, usos, benefícios, custos, peças, etapas, código e referências.</p><p>O catálogo é amplo e extensível. Não existe um inventário universal, fechado e estável de todos os padrões de software. Os nomes variam entre comunidades, e alguns representam estilos, protocolos, técnicas ou mecanismos, não padrões no mesmo nível de abstração.</p><div class="definition-list"><div><h3>Arquitetura</h3><p>Decisões sobre limites, dependências, estado, comunicação e implantação de um sistema.</p></div><div><h3>Padrão de implementação</h3><p>Uma forma de organizar responsabilidades no código. Os padrões GoF entram aqui, aplicados a backend.</p></div><div><h3>Peça de infraestrutura</h3><p>Um processo, banco, cache, broker ou serviço gerenciado que realiza uma responsabilidade.</p></div><div><h3>Blueprint</h3><p>Uma implementação de referência que torna as relações concretas. A marca escolhida não é requisito universal do padrão.</p></div></div></section><section><h2>Como usar este material</h2><ol><li>Descreva o problema, a carga, as restrições e a promessa de consistência.</li><li>Leia os trade-offs e os cenários em que a técnica deve ser evitada.</li><li>Clique nas peças do diagrama e examine quem possui o estado e quem pode falhar.</li><li>Implemente o exemplo no escopo declarado; teste sucesso, concorrência e falhas relevantes.</li><li>Consulte as fontes, registre a decisão e acompanhe o comportamento em operação.</li></ol><p>Trechos pequenos isolam um mecanismo. Planos conceituais, pseudocódigo e exemplos locais são identificados; não equivalem a uma plataforma pronta para produção. O projeto MVC para download é um laboratório local executável com testes.</p></section><section><h2>Fontes e marcas</h2><p>A curadoria inicial é de 28 de outubro de 2026. Os textos são explicações educacionais independentes, apoiadas em documentação primária. A referência de cada guia leva à documentação que deve ser consultada para versões, garantias e limites atuais.</p><p>Os logos das tecnologias e ícones AWS, Azure e Google Cloud vêm de fontes oficiais e são preservados. Identificam os produtos usados nos exemplos, sem sugerir endosso. Símbolos genéricos de cliente, serviço, banco e fila são desenhos próprios, não logos de fornecedores.</p><a class="button" href="assets/credits.json" target="_blank">Ver proveniência dos logos ↗</a></section><section><h2>Seu progresso é local</h2><p>Favoritos, estudos concluídos, comparação, tema e movimento são salvos somente neste navegador. Não existe conta ou sincronização. O portal não envia esses dados para um backend. Fontes tipográficas são carregadas do Google Fonts; a hospedagem GitHub Pages possui suas próprias políticas de acesso.</p><button class="button" data-action="export-progress">Exportar meu progresso ↓</button><p class="control-note">O JSON exportado é uma cópia para consulta. A importação não está disponível.</p></section><section><h2>Ajude a manter o atlas preciso</h2><p>Uma boa contribuição traz um problema concreto, uma explicação original, uma implementação com limites claros e uma fonte primária. Correções e aprofundamentos são bem-vindos.</p><a class="button primary" href="https://github.com/wesleyvieira99/DesignSystems/issues" target="_blank" rel="noreferrer">Contribuir no GitHub ↗</a></section></article>`;}
function updateGlobal(){
 $('#total-nav').textContent=entries.length;$('#compare-nav').textContent=compared.size;$('#favorites-nav').textContent=favorites.size;
 $('#learning-caption').textContent=completed.size?`${completed.size} de ${entries.length} guias estudados.`:'Seu progresso fica neste navegador.';
 $('#progress-orbit').style.setProperty('--progress',`${entries.length?completed.size/entries.length*100:0}%`);
 const tray=$('#compare-tray');tray.hidden=!compared.size||currentPath==='/comparar';
 tray.innerHTML=`<span><b>${compared.size}/3</b> para comparar</span><div class="tray-items">${[...compared].map(id=>`<span class="tray-item">${esc(byId.get(id).name)}</span>`).join('')}</div><a class="button primary small" href="#/comparar">Comparar ${icon('arrow')}</a><button class="mini-button" data-action="clear-compare" aria-label="Limpar comparação">${icon('close')}</button>`;
 const dark=document.documentElement.dataset.theme==='dark',reduced=document.documentElement.dataset.motion==='reduced';
 $('[data-action="theme"]').innerHTML=icon(dark?'sun':'moon');$('[data-action="theme"]').setAttribute('aria-label',dark?'Ativar tema claro':'Ativar tema escuro');
 $('[data-action="motion"]').setAttribute('aria-label',reduced?'Permitir animações':'Reduzir animações');$('[data-action="motion"]').setAttribute('aria-pressed',String(reduced));
}
let renderSerial=0;
function render(navigate=true){
 const serial=++renderSerial;observer?.disconnect();resetGraphs();
 const [path,query='']=(location.hash.slice(1)||'/').split('?');currentPath=path;currentQuery=new URLSearchParams(query);
 let html,nav,title;
 if(path==='/'){html=home();nav='home';title='System Design';}
 else if(['/biblioteca','/favoritos'].includes(path)){html=library(path==='/favoritos');nav=path==='/favoritos'?'favorites':currentQuery.get('tema')||currentQuery.get('categoria')||'library';title=path==='/favoritos'?'Minha coleção':'Biblioteca';}
 else if(path.startsWith('/guia/')){const e=byId.get(path.slice(6));html=article(e);nav=e?.category||'library';title=e?.name||'Guia não encontrado';}
 else if(path==='/comparar'){html=comparison();nav='compare';title='Comparar';}
 else if(path==='/trilhas'){html=tracks();nav='tracks';title='Trilhas de aprendizado';}
 else if(path==='/laboratorio'){sim={attempts:0,success:0,lines:[]};html=laboratory();nav='lab';title='Laboratório';}
 else if(path==='/cloud'){if(cloudProviders[currentQuery.get('provedor')])cloudProvider=currentQuery.get('provedor');html=cloudExplorer();nav='cloud';title='Cloud explorer';}
 else if(path==='/tecnologias'){html=technologyPage(entries);nav='technologies';title='Peças & tecnologias';}
 else if(path==='/sobre'){html=about();nav='';title='Sobre o atlas';}
 else {html=empty('Este caminho ainda não foi mapeado.','Volte para a biblioteca e encontre sua próxima ideia.');nav='';title='Página não encontrada';}
 main.innerHTML=`<div class="${navigate?'view-enter':''}">${html}</div>`;document.title=`${title} — System Atlas`;$('#breadcrumb-current').textContent=title;
 $$('[data-nav]').forEach(a=>{const active=a.dataset.nav===nav;a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');});
 if($('#library-results'))libraryResults();
 if(path.startsWith('/guia/')){
  observer=new IntersectionObserver(items=>{items.forEach(i=>{if(i.isIntersecting){$$('.article-toc a').forEach(a=>a.classList.toggle('active',a.dataset.anchor===i.target.id));}});},{rootMargin:'-10% 0px -60% 0px'});
  $$('.article-content section').forEach(el=>observer.observe(el));
 }
 hydrate(main);updateGlobal();closeMenu(false);
 if(navigate){window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}
 const art=$('.hero-art');if(art){art.addEventListener('pointermove',e=>{const r=art.getBoundingClientRect();art.style.setProperty('--rx',`${((e.clientX-r.left)/r.width-.5)*8}deg`);art.style.setProperty('--ry',`${((e.clientY-r.top)/r.height-.5)*-6}deg`);});art.addEventListener('pointerleave',()=>{art.style.setProperty('--rx','0deg');art.style.setProperty('--ry','0deg');});}
 requestAnimationFrame(()=>{if(serial===renderSerial)readingProgress();});
}
function readingProgress(){const body=$('.article-content'),bar=$('.reading-progress i');if(body&&bar){const rect=body.getBoundingClientRect();bar.style.width=`${Math.min(100,Math.max(0,(90-rect.top)/(rect.height-window.innerHeight+180)*100))}%`;}}
window.addEventListener('scroll',readingProgress,{passive:true});
function refreshPreservingFocus(button){const action=button?.dataset.action,id=button?.dataset.id,index=$$('.entry-card').indexOf(button?.closest('.entry-card'));render(false);if(action){const cards=$$('.card-link');const el=$$('[data-action]').find(x=>x.dataset.action===action&&x.dataset.id===id)||cards[Math.min(Math.max(index,0),cards.length-1)]||$('#catalog-search')||main;el.focus({preventScroll:true});}}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copiado para a área de transferência.');}catch{const area=document.createElement('textarea');area.value=text;area.setAttribute('aria-label','Texto para copiar');area.style.position='fixed';area.style.top='0';document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();toast(ok?'Copiado para a área de transferência.':'Não foi possível copiar. Selecione o texto do exemplo.');}}
let simRun=0,sim={attempts:0,success:0,lines:[]};
function simLog(text,type=''){sim.lines.push({text,type});$('#event-log').innerHTML=sim.lines.slice(-30).map(l=>`<div class="${l.type}">${esc(l.text)}</div>`).join('');$('#event-log').scrollTop=$('#event-log').scrollHeight;}
async function simulate(button){
 button.disabled=true;const run=++simRun,serial=renderSerial,push=$('#sim-push').checked,fail=$('#sim-fail').checked,invalid=$('#sim-invalid').checked;
 const reduced=document.documentElement.dataset.motion==='reduced'||matchMedia('(prefers-reduced-motion: reduce)').matches;
 const step=()=>new Promise(r=>setTimeout(r,reduced?0:350));
 $$('.sim-node').forEach(n=>n.classList.remove('active','failed'));$('#node-input').classList.add('active');simLog(`→ Evento: ${invalid?'(vazio)':'evt-001'} | push=${push}`);await step();if(serial!==renderSerial||run!==simRun)return;
 $('#node-input').classList.remove('active');$('#node-validate').classList.add('active');
 if(invalid){$('#node-validate').classList.add('failed');simLog('ValueError: evento_id deve ser uma string não vazia. Nenhum canal chamado.','error');button.disabled=false;return;}
 simLog('✓ Identificadores válidos.');await step();if(serial!==renderSerial||run!==simRun)return;
 $('#node-validate').classList.remove('active');$('#node-channel').classList.add('active');const channel=push?'PUSH':'SMS';sim.attempts++;$('#sim-attempts').textContent=sim.attempts;simLog(`→ ${channel}.enviar(alerta): tentativa ${sim.attempts}.`);await step();if(serial!==renderSerial||run!==simRun)return;
 if(fail){$('#node-channel').classList.add('failed');simLog('CanalIndisponivel: falha propagada; sem fallback.','error');}
 else {sim.success++;$('#sim-success').textContent=sim.success;simLog(`✓ Retorno: "${channel}". Envio concluído.`, 'ok');}
 button.disabled=false;
}
function openSearch(){closeMenu(false);$('#search-dialog').showModal();$('#command-search').setAttribute('aria-expanded','true');$('#command-search').value='';searchIndex=0;updateSearch();$('#command-search').focus();}
function closeSearch(){$('#search-dialog').close();$('#command-search').setAttribute('aria-expanded','false');}
function updateSearch(){searchResults=searchEntries(entries,$('#command-search').value).slice(0,9);searchIndex=0;$('#command-results').innerHTML=searchResults.length?searchResults.map((e,i)=>`<a id="command-option-${i}" role="option" aria-selected="${i===0}" tabindex="-1" class="command-result ${i===0?'highlighted':''}" href="${routeFor(e)}" data-result-index="${i}">${entryMark(e)}<span><strong>${esc(e.name)}</strong><small>${esc(e.organization)} · ${esc(e.kind)}</small></span>${icon('arrow-up-right')}</a>`).join(''):'<div class="empty-state"><p>Nenhum guia encontrado. Experimente outro termo.</p></div>';if(searchResults.length)$('#command-search').setAttribute('aria-activedescendant','command-option-0');else $('#command-search').removeAttribute('aria-activedescendant');}
const mobileQuery=matchMedia('(max-width: 800px)');
function closeMenu(returnFocus=true){const wasOpen=$('#sidebar').classList.contains('open');$('#sidebar').classList.remove('open');$('#mobile-backdrop').classList.remove('open');$('[data-action="menu"]').setAttribute('aria-expanded','false');$('#sidebar').inert=mobileQuery.matches;if(wasOpen&&returnFocus)$('[data-action="menu"]').focus();}
function toggleMenu(){const open=!$('#sidebar').classList.contains('open');$('#sidebar').classList.toggle('open',open);$('#mobile-backdrop').classList.toggle('open',open);$('#sidebar').inert=mobileQuery.matches&&!open;$('[data-action="menu"]').setAttribute('aria-expanded',String(open));if(open)$('#sidebar a').focus();}
mobileQuery.addEventListener('change',()=>closeMenu(false));$('#mobile-backdrop').addEventListener('click',()=>closeMenu());
document.addEventListener('input',e=>{if(e.target.id==='catalog-search')updateLibraryURL();if(e.target.id==='command-search')updateSearch();});
document.addEventListener('change',e=>{if(['level-filter','kind-filter'].includes(e.target.id))updateLibraryURL();if(e.target.id==='sort-filter')updateLibraryURL();});
document.addEventListener('click',async e=>{
 const b=e.target.closest('button,a');if(!b)return;
 if(b.classList.contains('skip-link')){e.preventDefault();main.focus();return;}
 if(b.matches('.command-result'))closeSearch();
 if(b.dataset.anchor){e.preventDefault();document.getElementById(b.dataset.anchor)?.scrollIntoView({behavior:(document.documentElement.dataset.motion==='reduced'||matchMedia('(prefers-reduced-motion: reduce)').matches)?'instant':'smooth'});return;}
 if(b.hasAttribute('data-category')){currentQuery.set('categoria',b.dataset.category);updateLibraryURL();$$('[data-category]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});$$('[data-nav]').forEach(x=>{const active=x.dataset.nav===(currentPath==='/favoritos'?'favorites':b.dataset.category||'library');x.classList.toggle('active',active);active?x.setAttribute('aria-current','page'):x.removeAttribute('aria-current');});return;}
 if(b.hasAttribute('data-topic')){currentQuery.set('tema',b.dataset.topic);currentQuery.delete('categoria');currentQuery.delete('tipo');$('#kind-filter').innerHTML='<option value="">Todos os tipos</option>'+[...new Set(entries.map(e=>e.kind))].sort().map(v=>`<option>${esc(v)}</option>`).join('');updateLibraryURL();$$('[data-topic]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});$$('[data-nav]').forEach(x=>{const active=x.dataset.nav===(currentPath==='/favoritos'?'favorites':b.dataset.topic||'library');x.classList.toggle('active',active);active?x.setAttribute('aria-current','page'):x.removeAttribute('aria-current');});return;}
 if(b.dataset.provider){cloudProvider=b.dataset.provider;cloudNode=0;history.replaceState(null,'',`#/cloud?provedor=${cloudProvider}`);render(false);$(`[data-provider="${cloudProvider}"]`).focus({preventScroll:true});return;}
 if(b.hasAttribute('data-node')){cloudNode=Number(b.dataset.node);$$('[data-node]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});$('#cloud-node-detail').innerHTML=cloudNodeDetail();return;}
 const action=b.dataset.action,id=b.dataset.id;
 if(action==='search')openSearch();
 else if(action==='close-search')closeSearch();
 else if(action==='theme'){const t=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=t;storage.setItem('atlas-backend-theme',t);updateGlobal();}
 else if(action==='motion'){const reduced=document.documentElement.dataset.motion!=='reduced';document.documentElement.dataset.motion=reduced?'reduced':'full';storage.setItem('atlas-motion',reduced?'reduced':'full');updateGlobal();toast(reduced?'Animações reduzidas.':'Animações permitidas, respeitando a preferência do sistema.');}
 else if(action==='menu')toggleMenu();
 else if(action==='favorite'){if(favorites.has(id))favorites.delete(id);else favorites.add(id);persist('favorites',favorites);refreshPreservingFocus(b);toast(favorites.has(id)?'Guia salvo na sua coleção.':'Guia removido da coleção.');}
 else if(action==='compare'){if(compared.has(id))compared.delete(id);else if(compared.size<3)compared.add(id);else{toast('Compare até três referências. Remova uma para adicionar outra.');return;}persist('compared',compared);refreshPreservingFocus(b);}
 else if(action==='clear-compare'){compared.clear();persist('compared',compared);render(false);}
 else if(action==='complete'){if(completed.has(id))completed.delete(id);else completed.add(id);persist('completed',completed);refreshPreservingFocus(b);toast(completed.has(id)?'Mais um conceito no seu repertório.':'Marcação de estudo removida.');}
 else if(action==='more'){const previous=libraryLimit;libraryLimit+=24;libraryResults();$$('.card-link')[previous]?.focus({preventScroll:true});}
 else if(action==='copy-example')copy(byId.get(id).example.code);
 else if(action==='copy-code'){const guide=byId.get(id);copy(b.dataset.code==='example'?guide.example.code:guide.walkthrough[Number(b.dataset.code.slice(5))].code);}
 else if(action==='copy-link')copy(location.href);
 else if(action==='simulate')simulate(b);
 else if(action==='reset-sim'){simRun++;$('[data-action="simulate"]').disabled=false;sim={attempts:0,success:0,lines:[]};$('#sim-attempts').textContent='0';$('#sim-success').textContent='0';$('#event-log').textContent='Aguardando o primeiro evento…';$('#sim-push').checked=true;$('#sim-fail').checked=false;$('#sim-invalid').checked=false;$$('.sim-node').forEach(n=>n.classList.remove('active','failed'));toast('Simulação de alertas reiniciada.');}
 else if(action==='export-progress'){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),favorites:[...favorites].map(id=>({id,name:byId.get(id).name})),completed:[...completed].map(id=>({id,name:byId.get(id).name}))},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='atlas-meu-progresso.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Seu progresso foi exportado.');}
});
$('#search-dialog').addEventListener('close',()=>$('#command-search').setAttribute('aria-expanded','false'));
$('#search-dialog').addEventListener('click',e=>{const r=e.currentTarget.getBoundingClientRect();if(e.target===e.currentTarget&&(e.clientY<r.top||e.clientY>r.bottom||e.clientX<r.left||e.clientX>r.right))closeSearch();});
document.addEventListener('keydown',e=>{
 const typing=/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName)||document.activeElement?.isContentEditable;
 if(((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k')||(!typing&&e.key==='/')){e.preventDefault();if($('#search-dialog').open)closeSearch();else openSearch();return;}
 if($('#search-dialog').open&&['ArrowDown','ArrowUp','Enter'].includes(e.key)&&document.activeElement===$('#command-search')){e.preventDefault();if(!searchResults.length)return;if(e.key==='Enter'){location.hash=routeFor(searchResults[searchIndex]);closeSearch();return;}searchIndex=(searchIndex+(e.key==='ArrowDown'?1:-1)+searchResults.length)%searchResults.length;$$('.command-result').forEach((x,i)=>{x.classList.toggle('highlighted',i===searchIndex);x.setAttribute('aria-selected',String(i===searchIndex));});$('#command-search').setAttribute('aria-activedescendant',`command-option-${searchIndex}`);$(`[data-result-index="${searchIndex}"]`).scrollIntoView({block:'nearest'});}
 if(e.key==='Escape'&&$('#sidebar').classList.contains('open'))closeMenu();
 if(e.key==='Tab'&&mobileQuery.matches&&$('#sidebar').classList.contains('open')){const focusable=$$('a,button',$('#sidebar'));const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
});
window.addEventListener('hashchange',()=>{libraryLimit=24;render();});
hydrate();closeMenu(false);
try{
 const response=await fetch('data/catalog.json');if(!response.ok)throw new Error(`HTTP ${response.status}`);const catalog=await response.json();entries=Array.isArray(catalog)?catalog:catalog.entries;byId=new Map(entries.map(e=>[e.id,e]));const known=new Set(byId.keys());favorites=loadList(storage,'atlas-favorites',known);completed=loadList(storage,'atlas-completed',known);compared=new Set([...loadList(storage,'atlas-compared',known)].slice(0,3));render();
}catch(error){main.innerHTML=empty('Não foi possível abrir a biblioteca.','Confira sua conexão e recarregue a página. Se você estiver desenvolvendo localmente, execute a geração do catálogo antes de iniciar o servidor.',false)+`<button class="button primary" onclick="location.reload()">Tentar novamente</button>`;console.error('Falha ao carregar o catálogo:',error);}
